css:
/* DIN 5008 Form A. The print format margins are top 10 mm and left/right 0 mm, so page positions are shifted by 10 mm. */
.erpverein-din5008 {
	position: relative;
	padding: 0 20mm 0 25mm;
	font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
	font-size: 10pt;
	line-height: 1.35;
	color: #000;
}

.erpverein-din5008 .din-letterhead {
	position: absolute;
	top: 0;
	left: 25mm;
	right: 20mm;
	height: 17mm;
	overflow: hidden;
}

.erpverein-din5008 .din-company-name {
	font-size: 14pt;
	font-weight: bold;
}

.erpverein-din5008 .din-address {
	position: absolute;
	top: 17mm;
	left: 20mm;
	width: 85mm;
	height: 45mm;
	overflow: hidden;
}

.erpverein-din5008 .din-return-line {
	display: flex;
	align-items: flex-end;
	height: 17.7mm;
	padding-left: 5mm;
	font-size: 7pt;
	line-height: 1.2;
}

.erpverein-din5008 .din-return-line span {
	display: block;
	width: 100%;
	padding-bottom: 1mm;
	border-bottom: 0.2mm solid #000;
}

.erpverein-din5008 .din-recipient {
	height: 27.3mm;
	padding: 1mm 0 0 5mm;
}

.erpverein-din5008 .din-info {
	position: absolute;
	top: 22mm;
	left: 125mm;
	width: 75mm;
	font-size: 9pt;
}

.erpverein-din5008 .din-info td {
	padding: 0 2mm 0.5mm 0;
	vertical-align: top;
}

.erpverein-din5008 .din-mark {
	position: absolute;
	left: 0;
	width: 5mm;
	border-top: 0.2mm solid #000;
}

.erpverein-din5008 .din-mark-fold-1 {
	top: 77mm;
}

.erpverein-din5008 .din-mark-hole {
	top: 138.5mm;
	width: 7mm;
}

.erpverein-din5008 .din-mark-fold-2 {
	top: 182mm;
}

.erpverein-din5008 .din-body {
	padding-top: 87mm;
}

.erpverein-din5008 .din-subject {
	margin-bottom: 4mm;
	font-size: 11pt;
	font-weight: bold;
}

.erpverein-din5008 table.din-items,
.erpverein-din5008 table.din-schedule {
	width: 100%;
	margin: 3mm 0;
	border-collapse: collapse;
}

.erpverein-din5008 table.din-items th,
.erpverein-din5008 table.din-items td,
.erpverein-din5008 table.din-schedule th,
.erpverein-din5008 table.din-schedule td {
	padding: 1mm 1.5mm;
	border-bottom: 0.2mm solid #999;
	text-align: left;
	vertical-align: top;
}

.erpverein-din5008 .din-num {
	text-align: right !important;
	white-space: nowrap;
}

.erpverein-din5008 .din-pos {
	width: 10mm;
}

.erpverein-din5008 table.din-totals {
	width: 80mm;
	margin-left: auto;
	border-collapse: collapse;
}

.erpverein-din5008 table.din-totals td {
	padding: 0.8mm 1.5mm;
}

.erpverein-din5008 .din-grand-total td {
	border-top: 0.3mm solid #000;
	font-weight: bold;
}

.erpverein-din5008 .din-section-title {
	margin-top: 6mm;
	font-weight: bold;
}

.erpverein-din5008 .din-note {
	margin-top: 3mm;
}

.erpverein-din5008 .din-small {
	font-size: 8pt;
	color: #333;
}

.erpverein-din5008 .din-terms {
	margin-top: 4mm;
}

.erpverein-din5008 .din-footer {
	margin-top: 8mm;
	padding-top: 2mm;
	border-top: 0.2mm solid #999;
	font-size: 8pt;
}
